"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// Advanced Spill Suppressor: removes key-colour spill (typically green) from
// foreground edges. Standard suppresses the excess of the key colour's
// dominant channel over the larger of the other two. Ultra additionally limits
// suppression to hues near the key colour (Tolerance), narrows the spill
// limit (Spill Range), and can put the removed light back as neutral
// brightness (Spill Color Correction, Luma Correction) or grey the pixel
// (Desaturate).
//
// The reference analyses the whole frame to pick the dominant channel in
// Standard mode; this port uses the dominant channel of the Key Color
// instead, which matches for green/blue screens and keeps the effect a
// deterministic single pass with no frame analysis.

function aspPrimary(color) {
  var r = color[0];
  var g = color[1];
  var b = color[2];
  if (g >= r && g >= b) return [1, 0, 2];
  if (b >= r && b >= g) return [2, 0, 1];
  return [0, 1, 2];
}

function aspHue(color) {
  var r = color[0];
  var g = color[1];
  var b = color[2];
  var mx = Math.max(r, Math.max(g, b));
  var mn = Math.min(r, Math.min(g, b));
  var d = mx - mn;
  if (d < 0.0000001) return 0;
  var h;
  if (mx === r) {
    h = (g - b) / d;
    if (g < b) h += 6;
    h /= 6;
  } else if (mx === g) {
    h = ((b - r) / d + 2) / 6;
  } else {
    h = ((r - g) / d + 4) / 6;
  }
  return h;
}

ZoidiumPluginApis.defineFilter.call(this, {
  displayName: "Advanced Spill Suppressor",
  fragShaderUrl: "/plugins/native-fx/shaders/fx_advspill.glsl",
  uniforms: {
    uvScale: { type: "v2", value: new THREE.Vector2(1, 1) },
    keyPrimary: { type: "f", value: 1 },
    keyOther1: { type: "f", value: 0 },
    keyOther2: { type: "f", value: 2 },
    suppression: { type: "f", value: 1 },
    spillRange: { type: "f", value: 0 },
    lumaCorrection: { type: "f", value: 0 },
    tolerance: { type: "f", value: 1 },
    desaturate: { type: "f", value: 0 },
    neutral: { type: "f", value: 0 },
    keyHue: { type: "f", value: 1 / 3 },
  },
  properties: {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    method: {
      dynamic: true,
      name: "Method",
      type: PZ.property.type.OPTION,
      value: 0,
      items: "Standard;Ultra",
    },
    keyColor: {
      dynamic: true,
      name: "Key Color",
      type: PZ.property.type.COLOR,
      value: [0, 1, 0],
    },
    suppression: {
      dynamic: true,
      name: "Suppression",
      type: PZ.property.type.NUMBER,
      value: 100,
      min: 0,
      max: 200,
      step: 1,
      decimals: 0,
    },
    tolerance: {
      dynamic: true,
      name: "Tolerance",
      type: PZ.property.type.NUMBER,
      value: 50,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    desaturate: {
      dynamic: true,
      name: "Desaturate",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    spillRange: {
      dynamic: true,
      name: "Spill Range",
      type: PZ.property.type.NUMBER,
      value: 50,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    spillColorCorrection: {
      dynamic: true,
      name: "Spill Color Correction",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
    lumaCorrection: {
      dynamic: true,
      name: "Luma Correction",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
    },
  },
  update(frame) {
    if (!this.pass) return;
    var uniforms = this.pass.uniforms;
    this.pass.enabled = this.properties.enabled.get(frame) === 1;
    var ultra = this.properties.method.get(frame) === 1;
    var key = this.properties.keyColor.get(frame);
    var order = aspPrimary(key);
    uniforms.keyPrimary.value = order[0];
    uniforms.keyOther1.value = order[1];
    uniforms.keyOther2.value = order[2];
    uniforms.keyHue.value = aspHue(key);
    uniforms.suppression.value = this.properties.suppression.get(frame) / 100;
    if (ultra) {
      uniforms.tolerance.value = this.properties.tolerance.get(frame) / 100;
      uniforms.desaturate.value = this.properties.desaturate.get(frame) / 100;
      uniforms.spillRange.value = this.properties.spillRange.get(frame) / 100;
      uniforms.neutral.value = this.properties.spillColorCorrection.get(frame) / 100;
      uniforms.lumaCorrection.value = this.properties.lumaCorrection.get(frame) / 100;
    } else {
      uniforms.tolerance.value = 1;
      uniforms.desaturate.value = 0;
      uniforms.spillRange.value = 0;
      uniforms.neutral.value = 0;
      uniforms.lumaCorrection.value = 0;
    }
  },
});

text./plugins/native-fx/effects/beam.js:
"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// Native FX (filter): Beam. A laser beam from Starting Point to Ending Point.
// Length (%) and Time (%) select the visible portion of the segment
// (t0 = time * (1 - length), t1 = t0 + length); thickness lerps from Starting
// to Ending Thickness; Softness blends Inside Color into Outside Color across
// the beam. With 3D Perspective on, thickness follows the beam's position
// between the two points; with it off, the visible head and tail take the
// starting and ending thickness. Deterministic closed form per pixel.
var fxgenBeamEffect = this;

function beamNumber(property, frame, fallback) {
  try {
    const value = Number(property && property.get && property.get(frame));
    return Number.isFinite(value) ? value : fallback;
  } catch (_error) {
    return fallback;
  }
}

function beamVector(property, frame, fallback) {
  try {
    const value = property && property.get && property.get(frame);
    if (Array.isArray(value) && Number.isFinite(Number(value[0])) && Number.isFinite(Number(value[1]))) {
      return [Number(value[0]), Number(value[1])];
    }
  } catch (_error) {
    // Fall through to the fallback below.
  }
  return fallback.slice();
}

function beamColor(property, frame, fallback) {
  try {
    const value = property && property.get && property.get(frame);
    if (Array.isArray(value) && value.length >= 3) {
      const r = Number(value[0]);
      const g = Number(value[1]);
      const b = Number(value[2]);
      if (Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b)) return [r, g, b];
    }
  } catch (_error) {
    // Fall through to the fallback below.
  }
  return fallback.slice();
}

function beamPoint(name, fallback) {
  return {
    dynamic: true,
    group: true,
    name,
    type: PZ.property.type.VECTOR2,
    objects: [
      { dynamic: true, name: `${name}.X`, type: PZ.property.type.NUMBER, value: fallback[0], step: 0.01, decimals: 3 },
      { dynamic: true, name: `${name}.Y`, type: PZ.property.type.NUMBER, value: fallback[1], step: 0.01, decimals: 3 },
    ],
  };
}

ZoidiumPluginApis.defineFilter.call(fxgenBeamEffect, {
  displayName: "Beam",
  fragShaderUrl: "/plugins/native-fx/shaders/fx_beam.glsl",
  uniforms: {
    uvScale: { type: "v2", value: new THREE.Vector2(1, 1) },
    resolution: { type: "v2", value: new THREE.Vector2(1, 1) },
    uStart: { type: "v2", value: new THREE.Vector2(0.25, 0.5) },
    uEnd: { type: "v2", value: new THREE.Vector2(0.75, 0.5) },
    uWindow: { type: "v3", value: new THREE.Vector3(0, 0.25, 0.25) },
    uThick: { type: "v2", value: new THREE.Vector2(8, 8) },
    uSoft: { type: "f", value: 0.2 },
    uInside: { type: "v3", value: new THREE.Vector3(1, 1, 1) },
    uOutside: { type: "v3", value: new THREE.Vector3(0.4, 0.4, 1) },
    uPersp: { type: "f", value: 1 },
    uComposite: { type: "f", value: 1 },
  },
  properties: {
    enabled: { dynamic: true, name: "Enabled", type: PZ.property.type.OPTION, value: 1, items: "off;on" },
    startPoint: beamPoint("Starting Point", [0.25, 0.5]),
    endPoint: beamPoint("Ending Point", [0.75, 0.5]),
    length: { dynamic: true, name: "Length (%)", type: PZ.property.type.NUMBER, value: 25, min: 0, max: 100, step: 1, decimals: 1 },
    time: { dynamic: true, name: "Time (%)", type: PZ.property.type.NUMBER, value: 0, min: 0, max: 100, step: 1, decimals: 1 },
    startThickness: { dynamic: true, name: "Starting Thickness (px)", type: PZ.property.type.NUMBER, value: 8, min: 0, max: 1000, step: 0.5, decimals: 1 },
    endThickness: { dynamic: true, name: "Ending Thickness (px)", type: PZ.property.type.NUMBER, value: 8, min: 0, max: 1000, step: 0.5, decimals: 1 },
    softness: { dynamic: true, name: "Softness (%)", type: PZ.property.type.NUMBER, value: 20, min: 0, max: 100, step: 1, decimals: 1 },
    insideColor: { dynamic: true, name: "Inside Color", type: PZ.property.type.COLOR, value: [1, 1, 1] },
    outsideColor: { dynamic: true, name: "Outside Color", type: PZ.property.type.COLOR, value: [0.4, 0.4, 1] },
    perspective: { dynamic: true, name: "3D Perspective", type: PZ.property.type.OPTION, value: 1, items: "off;on" },
    composite: { dynamic: true, name: "Composite on Original", type: PZ.property.type.OPTION, value: 1, items: "off;on" },
  },
  update(frame) {
    if (!this.pass) return;
    this.pass.enabled = beamNumber(this.properties.enabled, frame, 1) === 1;
    const uniforms = this.pass.uniforms;
    const start = beamVector(this.properties.startPoint, frame, [0.25, 0.5]);
    const end = beamVector(this.properties.endPoint, frame, [0.75, 0.5]);
    const len = Math.min(1, Math.max(0, beamNumber(this.properties.length, frame, 25) / 100));
    const tm = Math.min(1, Math.max(0, beamNumber(this.properties.time, frame, 0) / 100));
    const t0 = tm * (1 - len);
    const inside = beamColor(this.properties.insideColor, frame, [1, 1, 1]);
    const outside = beamColor(this.properties.outsideColor, frame, [0.4, 0.4, 1]);
    uniforms.uStart.value.set(start[0], start[1]);
    uniforms.uEnd.value.set(end[0], end[1]);
    uniforms.uWindow.value.set(t0, t0 + len, len);
    uniforms.uThick.value.set(
      beamNumber(this.properties.startThickness, frame, 8),
      beamNumber(this.properties.endThickness, frame, 8),
    );
    uniforms.uSoft.value = Math.min(1, Math.max(0, beamNumber(this.properties.softness, frame, 20) / 100));
    uniforms.uInside.value.set(inside[0], inside[1], inside[2]);
    uniforms.uOutside.value.set(outside[0], outside[1], outside[2]);
    uniforms.uPersp.value = beamNumber(this.properties.perspective, frame, 1) === 1 ? 1 : 0;
    uniforms.uComposite.value = beamNumber(this.properties.composite, frame, 1) === 1 ? 1 : 0;
  },
});

text./plugins/native-fx/effects/cardwipe.js:
"use strict";

// Algorithm adapted from EffectCraft (MIT OR Apache-2.0).
//
// Card Wipe: the layer flips away as a grid of cards rotating in place.
// The fragment shader inverse-maps each card (rotation + simple
// perspective), so completion 0% passes the layer through exactly and 100%
// shows only the card backs. Per-card randomness (axis/direction coins,
// timing jitter) is derived deterministically from (seed, card index) on
// the CPU and uploaded as a small float data texture; the shader itself
// needs no integer math. Only the uniforms, properties and per-frame
// updates below are unique to this effect; pass plumbing comes from
// ZoidiumPluginApis.defineFilter.

var cardWipeEffect = this;

var cardWipeMath = (function loadCardWipeMath() {
  var getAsset = cardWipeEffect && cardWipeEffect._zoidiumGetAsset;
  var apis = typeof ZoidiumPluginApis !== "undefined" ? ZoidiumPluginApis : null;
  var createRequire = apis && apis.modules && apis.modules.createRequire;
  if (typeof getAsset !== "function" || typeof createRequire !== "function") {
    throw new Error("Card Wipe needs its bundle math (this._zoidiumGetAsset and ZoidiumPluginApis.modules.createRequire).");
  }
  var loader = createRequire(getAsset, { root: "./plugins/native-fx/", scope: {} });
  return loader("./effects/fxtrans-math.js");
})();

var cardWipeRand = {
  texture: null,
  signature: "",
  size: 0,
};

function cardWipeNumber(value, fallback) {
  var number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function cardWipeGrid(value, fallback) {
  var grid = Math.round(cardWipeNumber(value, fallback));
  if (!Number.isFinite(grid)) grid = fallback;
  return Math.min(64, Math.max(1, grid));
}

function cardWipeRefreshTexture(effect, cols, rows, randomSeed) {
  var seed = cardWipeMath.foldSeed(randomSeed);
  var signature = cols + "x" + rows + ":" + (seed | 0);
