  displayName: "CC Wide Time",
  properties: {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    forwardSteps: {
      dynamic: true,
      name: "Forward Steps",
      type: PZ.property.type.NUMBER,
      value: 3,
