      ccWideTimeEffect._zoidiumWideTimeCopyPass = copyPass;
      ccWideTimeEffect._zoidiumWideTimeTargets = [];
      ccWideTimeEffect._zoidiumWideTimeAccumulate = 0;
      ccWideTimeEffect.pass = {
        enabled: true,
