    },
    update(frame) {
      if (!ccWideTimeEffect.pass) return;
      const { forward, backward } = ccWideTimeSteps(ccWideTimeEffect.properties, frame);
      ccWideTimeEffect.pass.enabled =
        ccWideTimeNumber(ccWideTimeEffect.properties.enabled, frame, 1) === 1 &&
        forward + backward >= 1;
