      value: 100,
      min: 100,
      max: 500,
      step: 1,
      decimals: 0,
    },
    strength: {
      dynamic: true,
      name: "Strength",
      type: PZ.property.type.NUMBER,
      value: 100,
      min: 0,
      max: 100,
      step: 1,
      decimals: 0,
