"use strict";

// Native FX (temporal): declares a deterministic time-shift operator.
// The host applies it in plugins/core/temporal-render.js; this file only
// describes properties and how to read the operator for a frame.
ZoidiumPluginApis.defineTemporal.call(this, {
  kind: "time-offset",
  displayName: "Time Offset",
  properties: {
    enabled: {
      dynamic: true,
      name: "Enabled",
      type: PZ.property.type.OPTION,
      value: 1,
      items: "off;on",
    },
    offset: {
      dynamic: true,
      name: "Offset (frames)",
      type: PZ.property.type.NUMBER,
      value: 0,
      min: -100000,
      max: 100000,
      step: 1,
      decimals: 3,
    },
  },
  getOperator(effect, frame) {
    return {
      kind: "time-offset",
      enabled: effect.properties.enabled.get(frame) === 1,
      offsetFrames: Number(effect.properties.offset.get(frame)) || 0,
    };
  },
});

text./plugins/native-fx/shaders/fx_advspill.g:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform float keyPrimary;
uniform float keyOther1;
uniform float keyOther2;
uniform float suppression;
uniform float spillRange;
uniform float lumaCorrection;
uniform float tolerance;
uniform float desaturate;
uniform float neutral;
uniform float keyHue;

float aspPick(vec3 c, float idx) {
  if (idx < 0.5) {
    return c.r;
  }
  if (idx < 1.5) {
    return c.g;
  }
  return c.b;
}

float aspLumaWeight(float idx) {
  if (idx < 0.5) {
    return 0.2126;
  }
  if (idx < 1.5) {
    return 0.7152;
  }
  return 0.0722;
}

float aspHue(vec3 c) {
  float mx = max(c.r, max(c.g, c.b));
  float mn = min(c.r, min(c.g, c.b));
  float d = mx - mn;
  if (d < 0.0000001) {
    return 0.0;
  }
  float h;
  if (mx == c.r) {
    h = (c.g - c.b) / d;
    if (c.g < c.b) {
      h += 6.0;
    }
    h /= 6.0;
  } else if (mx == c.g) {
    h = ((c.b - c.r) / d + 2.0) / 6.0;
  } else {
    h = ((c.r - c.g) / d + 4.0) / 6.0;
  }
  return h;
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (px.a <= 0.0) {
    gl_FragColor = px;
    return;
  }
  vec3 s = px.rgb / px.a;
  float w = 1.0;
  if (tolerance < 1.0) {
    float h = aspHue(s);
    float d0 = abs(h - keyHue);
    float d = min(d0, 1.0 - d0);
    w = clamp(1.0 - d / max(tolerance * 0.5, 0.0001), 0.0, 1.0);
  }
  float cO1 = aspPick(s, keyOther1);
  float cO2 = aspPick(s, keyOther2);
  float mx = max(cO1, cO2);
  float avg = 0.5 * (cO1 + cO2);
  float lim = mx + (avg - mx) * spillRange;
  float spill = max(aspPick(s, keyPrimary) - lim, 0.0) * suppression * w;
  float back = spill * aspLumaWeight(keyPrimary) * lumaCorrection + spill * neutral / 3.0;
  vec3 outc = s + vec3(back);
  if (keyPrimary < 0.5) {
    outc.r -= spill;
  } else if (keyPrimary < 1.5) {
    outc.g -= spill;
  } else {
    outc.b -= spill;
  }
  if (desaturate > 0.0 && spill > 0.0) {
    float l = 0.2126 * outc.r + 0.7152 * outc.g + 0.0722 * outc.b;
    float k = min(desaturate * min(spill * 4.0, 1.0), 1.0);
    outc += (vec3(l) - outc) * k;
  }
  gl_FragColor = vec4(outc * px.a, px.a);
}

text./plugins/native-fx/shaders/fx_beam.glsl:
// Beam (NATIVE FX): a laser beam between Starting and Ending Point. Closed
// form per pixel: the Length/Time window selects the visible portion of the
// segment, thickness lerps from Starting to Ending Thickness (in beam space
// with 3D Perspective on, in head/tail space with it off), and the edge
// blends from Inside to Outside Color with Softness.
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform vec2 uStart;      // starting point, 0..1 of the buffer (y down)
uniform vec2 uEnd;        // ending point, 0..1 of the buffer (y down)
uniform vec3 uWindow;     // t0, t1, length (0 = no beam)
uniform vec2 uThick;      // starting / ending thickness in px
uniform float uSoft;      // 0..1 softness
uniform vec3 uInside;
uniform vec3 uOutside;
uniform float uPersp;     // 3D perspective on/off
uniform float uComposite; // composite on original on/off

float zss(float e0, float e1, float x) {
  float t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

vec4 over(vec4 dst, vec4 src) {
  return src + dst * (1.0 - src.a);
}

void main() {
  vec2 p = vec2(vUv.x * resolution.x, (1.0 - vUv.y) * resolution.y);
  vec2 s = vec2(uStart.x * resolution.x, uStart.y * resolution.y);
  vec2 e = vec2(uEnd.x * resolution.x, uEnd.y * resolution.y);
  vec2 d = e - s;
  float l2 = max(dot(d, d), 1e-9);
  vec2 v = p - s;
  float tc = clamp(dot(v, d) / l2, uWindow.x, uWindow.y);
  vec2 q = s + d * tc;
  float dist = length(p - q);
  float tk = tc;
  if (uPersp < 0.5 && (uWindow.y - uWindow.x) >= 1e-9) {
    tk = (tc - uWindow.x) / (uWindow.y - uWindow.x);
  }
  float hw = max((uThick.x + (uThick.y - uThick.x) * tk) * 0.5, 0.25);
  float tt = dist / hw;
  float a = 0.0;
  if (uWindow.z > 0.0) {
    if (uSoft > 1e-3) {
      a = 1.0 - zss(1.0 - uSoft, 1.0, tt);
    } else {
      a = clamp(hw - dist + 0.5, 0.0, 1.0);
    }
  }
  vec3 cc = uInside + (uOutside - uInside) * zss(0.0, 1.0, tt);
  vec4 beam = vec4(cc * a, a);
  if (uComposite > 0.5) {
    vec4 base = texture2D(tDiffuse, vUv * uvScale);
    gl_FragColor = over(base, beam);
  } else {
    gl_FragColor = beam;
  }
}

text./plugins/native-fx/shaders/fx_cardwipe.g:
// Card Wipe: the layer flips away as a grid of cards rotating in place.
// Each output pixel belongs to its own grid cell (cards never translate),
// so the shader inverse-maps the card rotation + simple perspective exactly.
// Per-card randomness (axis/direction coins, timing jitter) arrives in the
// tRand data texture generated on the CPU from (seed, card index), keeping
// the shader free of integer math. All sampling goes through uvScale.
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;
uniform sampler2D tRand;

uniform float rows;
uniform float columns;
uniform float cardScale;
uniform float flipAxis;
uniform float flipDirection;
uniform float flipOrder;
uniform float timingRandomness;
uniform float completion;
uniform float transitionWidth;
uniform float backMode;
uniform vec3 backColor;
uniform float cameraDist;
uniform float lightIntensity;
uniform float ambient;

#define PI 3.141592653589793

vec4 sampleLayer(vec2 luv) {
  if (luv.x < 0.0 || luv.x > 1.0 || luv.y < 0.0 || luv.y > 1.0) {
    return vec4(0.0);
  }
  return texture2D(tDiffuse, luv * uvScale);
}

vec3 straightOf(vec4 px) {
  if (px.a > 0.00001) {
    return px.rgb / px.a;
  }
  return vec3(0.0);
}

void main() {
  vec2 grid = vec2(max(columns, 1.0), max(rows, 1.0));
  vec2 id = floor(vUv * grid);
  id = min(id, grid - 1.0);
  vec2 cc = (id + 0.5) / grid;
  float nx = grid.x > 1.5 ? id.x / (grid.x - 1.0) : 0.0;
  float ny = grid.y > 1.5 ? id.y / (grid.y - 1.0) : 0.0;
  float order = flipOrder;
  float o = nx;
  if (order < 0.5) {
    o = nx;
  } else if (order < 1.5) {
    o = 1.0 - nx;
  } else if (order < 2.5) {
    o = ny;
  } else if (order < 3.5) {
    o = 1.0 - ny;
  } else if (order < 4.5) {
    o = (nx + ny) * 0.5;
  } else if (order < 5.5) {
    o = (1.0 - nx + ny) * 0.5;
  } else if (order < 6.5) {
    o = (nx + 1.0 - ny) * 0.5;
  } else if (order < 7.5) {
    o = 1.0 - (nx + ny) * 0.5;
  } else {
    vec4 g = sampleLayer(cc);
    vec3 sc = straightOf(g);
    o = clamp(0.2126 * sc.x + 0.7152 * sc.y + 0.0722 * sc.z, 0.0, 1.0);
  }
  vec4 rnd = texture2D(tRand, (id + 0.5) / grid);
  o = o + (rnd.b - o) * clamp(timingRandomness, 0.0, 1.0);
  float tw = clamp(transitionWidth, 0.01, 1.0);
  float p = clamp((completion - o * (1.0 - tw)) / tw, 0.0, 1.0);
  if (p <= 0.0) {
    gl_FragColor = texture2D(tDiffuse, vUv * uvScale);
    return;
  }
  bool aroundX = true;
  if (flipAxis < 0.5) {
    aroundX = true;
  } else if (flipAxis < 1.5) {
    aroundX = false;
  } else {
    aroundX = rnd.r < 0.5;
  }
  float sign = 1.0;
  if (flipDirection < 0.5) {
    sign = 1.0;
  } else if (flipDirection < 1.5) {
    sign = -1.0;
  } else {
    sign = rnd.g < 0.5 ? -1.0 : 1.0;
  }
  float a = p * PI * sign;
  float cosA = cos(a);
  float sinA = sin(a);
  if (abs(cosA) < 0.004) {
    gl_FragColor = vec4(0.0);
    return;
  }
  bool front = cosA >= 0.0;
  float aspect = resolution.x / max(resolution.y, 1.0);
  vec2 rel = vec2((vUv.x - cc.x) * aspect, vUv.y - cc.y);
  vec2 halfCard = vec2(0.5 * aspect / grid.x, 0.5 / grid.y);
  float D = max(cameraDist, 1.0);
  float lx;
  float ly;
  if (aroundX) {
    ly = rel.y * D / (cosA * D - rel.y * sinA);
    float s = D / (D - ly * sinA);
    lx = rel.x / s;
  } else {
    lx = rel.x * D / (cosA * D - rel.x * sinA);
    float s = D / (D - lx * sinA);
    ly = rel.y / s;
  }
  float pic = max(cardScale, 1.0);
  vec2 ext = halfCard * min(cardScale, 1.0);
  // Half-texel tolerance: card edges shared with a neighbour must not drop
  // out from a ulp of inversion noise.
  if (abs(lx) > ext.x + 1e-4 || abs(ly) > ext.y + 1e-4) {
    gl_FragColor = vec4(0.0);
    return;
  }
  float bright = lightIntensity * (ambient + (1.0 - ambient) * (0.3 + 0.7 * abs(cosA)));
  if (!front) {
    if (backMode > 0.5) {
      gl_FragColor = vec4(0.0);
      return;
    }
    gl_FragColor = vec4(backColor * bright, 1.0);
    return;
  }
  vec2 srcLocal = vec2(lx, ly) / pic;
  vec2 luv = cc + vec2(srcLocal.x / aspect, srcLocal.y);
  vec4 texel = sampleLayer(luv);
  gl_FragColor = vec4(texel.rgb * bright, texel.a);
}

text./plugins/native-fx/shaders/fx_ccpageturn:
// CC Page Turn: analytic cylinder curl of the layer around a fold line.
// vUv.y = 0 is the image top (like CM3 image pixels), so the reference
// image-space math ports directly. All sampling goes through uvScale.
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform vec2 foldPos;
uniform float foldDir;
uniform float foldRadius;
uniform float lightDir;
uniform float renderMode;
uniform float backOpacity;
uniform vec3 paperColor;
uniform float backSource;

#define PI 3.141592653589793

vec4 sampleLayer(vec2 luv) {
  if (luv.x < 0.0 || luv.x > 1.0 || luv.y < 0.0 || luv.y > 1.0) {
    return vec4(0.0);
  }
  return texture2D(tDiffuse, luv * uvScale);
}

// Evaluate one curl candidate. sampled = false means the caller must try
// the next candidate (hidden by Render mode or transparent source).
vec4 evalCandidate(float u, float isBack, float shade, vec2 s, vec2 n, float d, float aspect, out bool sampled) {
  bool back = isBack > 0.5;
  bool showFront = renderMode < 0.5 || renderMode > 1.5;
  bool showBack = renderMode < 1.5;
  sampled = false;
  if ((back && !showBack) || (!back && !showFront)) {
    return vec4(0.0);
  }
  vec2 sq = s + (u - d) * n;
  vec2 luv = vec2(sq.x / aspect, sq.y);
  vec4 v = sampleLayer(luv);
  if (v.a <= 0.0001) {
    return vec4(0.0);
  }
  vec3 c = v.a > 0.00001 ? v.rgb / v.a : vec3(0.0);
  if (back) {
    if (backSource > 0.5) {
      c = paperColor;
    } else {
      c = paperColor * (1.0 - backOpacity) + c * backOpacity;
    }
  }
  sampled = true;
  return vec4(c * shade * v.a, v.a);
}

void main() {
  float aspect = resolution.x / max(resolution.y, 1.0);
  vec2 ar = vec2(aspect, 1.0);
  vec2 s = vUv * ar;
  vec2 sf = foldPos * ar;
  float phi = radians(foldDir);
  vec2 n = vec2(-sin(phi), cos(phi));
  float lam = radians(lightDir);
  float ldot = n.x * sin(lam) - n.y * cos(lam);
  float resY = max(resolution.y, 1.0);
  float r = max(foldRadius / resY, 0.5 / resY);
  float d = dot(s - sf, n);
  if (d > r) {
    gl_FragColor = vec4(0.0);
    return;
  }
  float u1;
  float b1;
  float sh1;
  float u2;
  float b2;
  float sh2;
  if (d <= 0.0) {
    u1 = PI * r - d;
    b1 = 1.0;
    sh1 = 0.9;
    u2 = d;
    b2 = 0.0;
    sh2 = 1.0;
  } else {
    float a = asin(clamp(d / r, -1.0, 1.0));
    u1 = PI * r - r * a;
    b1 = 1.0;
    sh1 = 0.6 + 0.4 * cos(a);
    float psi = a / (PI * 0.5);
    u2 = r * a;
    b2 = 0.0;
    sh2 = 1.0 - 0.4 * psi * (0.5 + 0.5 * ldot);
  }
  bool ok = false;
  vec4 c1 = evalCandidate(u1, b1, sh1, s, n, d, aspect, ok);
  if (ok) {
    gl_FragColor = c1;
    return;
  }
  vec4 c2 = evalCandidate(u2, b2, sh2, s, n, d, aspect, ok);
  if (ok) {
    gl_FragColor = c2;
    return;
  }
  gl_FragColor = vec4(0.0);
}

text./plugins/native-fx/shaders/fx_ccwidetime:
// CC Wide Time (Native FX): one weighted-accumulation pass. The host evaluates
// the current frame (tBase on the first pass) plus explicitly requested
// forward/backward frame taps; this shader folds one tap texture per pass into
// the running total. Average mode divides by the tap count (uniform weight);
// accumulate mode sums like a photographic shutter. Sampled with uv * uvScale
// because CM3 effect buffers can be larger than the layer.
precision highp float;

uniform sampler2D tAcc;
uniform sampler2D tFrame;
uniform float uWeight;
uniform int uInit;
uniform int uAccumulate;

varying vec2 vUvScaled;

void main() {
  vec4 frame = texture2D(tFrame, vUvScaled);
  if (uInit != 0) {
    if (uAccumulate != 0) {
      gl_FragColor = frame;
    } else {
      gl_FragColor = frame * uWeight;
    }
    return;
  }
  vec4 acc = texture2D(tAcc, vUvScaled);
  if (uAccumulate != 0) {
    gl_FragColor = vec4(acc.rgb + frame.rgb, min(1.0, acc.a + frame.a));
  } else {
    gl_FragColor = acc + frame * uWeight;
  }
}

text./plugins/native-fx/shaders/fx_colorcurve:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform sampler2D curveLUT;
uniform vec2 uvScale;

varying vec2 vUv;

void main() {
  vec2 sourceUv = vUv * uvScale;
  vec4 tex = texture2D(tDiffuse, sourceUv);
  float alpha = clamp(tex.a, 0.0, 1.0);
  vec3 straight = alpha > 0.00001 ? tex.rgb / alpha : vec3(0.0);
  vec3 lookupUv = (clamp(straight, 0.0, 1.0) * 255.0 + 0.5) / 256.0;
  vec3 graded;
  graded.r = texture2D(curveLUT, vec2(lookupUv.r, 0.5)).r;
  graded.g = texture2D(curveLUT, vec2(lookupUv.g, 0.5)).g;
  graded.b = texture2D(curveLUT, vec2(lookupUv.b, 0.5)).b;
  gl_FragColor = vec4(graded * alpha, alpha);
}

text./plugins/native-fx/shaders/fx_colordiffk:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform vec3 keyColor;
uniform float keyDiff1;
uniform float keyDiff2;
uniform float keyPrimary;
uniform float keyOther1;
uniform float keyOther2;
uniform float accurate;
uniform float view;
uniform vec4 partialA;
uniform vec4 partialB;
uniform float partialAGamma;
uniform float partialBGamma;
uniform vec3 matteLevels;

float cdkLinear(float v) {
  if (v <= 0.04045) {
    return v / 12.92;
  }
  return pow((v + 0.055) / 1.055, 2.4);
}

float cdkPick(vec3 c, float idx) {
  if (idx < 0.5) {
    return c.r;
  }
  if (idx < 1.5) {
    return c.g;
  }
  return c.b;
}

float cdkLevels(float v, float inBlack, float inWhite, float gamma, float outBlack, float outWhite) {
  float t = clamp((v - inBlack / 255.0) / max((inWhite - inBlack) / 255.0, 0.0001), 0.0, 1.0);
  t = pow(t, 1.0 / max(gamma, 0.01));
  return clamp(outBlack / 255.0 + t * (outWhite - outBlack) / 255.0, 0.0, 1.0);
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (view > 0.5 && view < 1.5) {
    gl_FragColor = px;
    return;
  }
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  if (accurate > 0.5) {
    c = vec3(
      cdkLinear(clamp(c.r, 0.0, 1.0)),
      cdkLinear(clamp(c.g, 0.0, 1.0)),
      cdkLinear(clamp(c.b, 0.0, 1.0))
    );
  }
  float ua = 1.0 - clamp((cdkPick(c, keyPrimary) - cdkPick(c, keyOther1)) / keyDiff1, 0.0, 1.0);
  float ub = 1.0 - clamp((cdkPick(c, keyPrimary) - cdkPick(c, keyOther2)) / keyDiff2, 0.0, 1.0);
  float ca = cdkLevels(ua, partialA.x, partialA.y, partialAGamma, partialA.z, partialA.w);
  float cb = cdkLevels(ub, partialB.x, partialB.y, partialBGamma, partialB.z, partialB.w);
  float um = max(ua, ub);
  float cm = cdkLevels(max(ca, cb), matteLevels.x, matteLevels.y, matteLevels.z, 0.0, 255.0);
  if (view > 1.5) {
    float g = cm;
    if (view > 2.5 && view < 3.5) {
      g = um;
    } else if (view > 3.5 && view < 4.5) {
      g = ca;
    } else if (view > 4.5) {
      g = cb;
    }
    float m = g * a0;
    gl_FragColor = vec4(m, m, m, 1.0);
    return;
  }
  gl_FragColor = px * cm;
}

text./plugins/native-fx/shaders/fx_keycleaner:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float chatter;
uniform float contrast;
uniform float strength;
uniform float estSigma;
uniform float estStep;

void main() {
  vec2 uv = vUv * uvScale;
  vec2 texel = vec2(
    uvScale.x / max(resolution.x, 1.0),
    uvScale.y / max(resolution.y, 1.0)
  );
  vec4 px = texture2D(tDiffuse, uv);
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  float na = a0;
  if (chatter > 0.5) {
    float sum = 0.0;
    for (int j = -2; j <= 2; j++) {
      for (int i = -2; i <= 2; i++) {
        sum += texture2D(tDiffuse, uv + vec2(float(i), float(j)) * texel).a;
      }
    }
    na = clamp((sum / 25.0 - 0.5) * 1.5 + 0.5, 0.0, 1.0);
  }
  if (estSigma > 0.001 && strength > 0.001 && a0 > 0.0001 && a0 < 0.999) {
    float sig2 = 2.0 * estSigma * estSigma;
    vec3 csum = vec3(0.0);
    float asum = 0.0;
    for (int j = -2; j <= 2; j++) {
      for (int i = -2; i <= 2; i++) {
        vec2 off = vec2(float(i), float(j)) * estStep * texel;
        float d2 = float(i * i + j * j) * estStep * estStep;
        float w = exp(-d2 / sig2);
        vec4 q = texture2D(tDiffuse, uv + off);
        csum += q.rgb * w;
        asum += max(q.a, 0.0) * w;
      }
    }
    if (asum > 0.0001) {
      float t = strength * (1.0 - a0);
      c += (csum / asum - c) * t;
    }
  }
  na = clamp((na - 0.5) * contrast + 0.5, 0.0, 1.0);
  if (a0 <= 0.000001) {
    na = 0.0;
  }
  gl_FragColor = vec4(c * na, na);
}

text./plugins/native-fx/shaders/fx_linearcolo:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;

uniform vec3 keyColor;
uniform float matchMode;
uniform float tolerance;
uniform float softness;
uniform float keep;
uniform float view;

vec3 lckHsl(vec3 c) {
  float mx = max(c.r, max(c.g, c.b));
  float mn = min(c.r, min(c.g, c.b));
  float l = (mx + mn) * 0.5;
  float d = mx - mn;
  if (d < 0.0000001) {
    return vec3(0.0, 0.0, l);
  }
  float s = l > 0.5 ? d / (2.0 - mx - mn) : d / (mx + mn);
  float h;
  if (mx == c.r) {
    h = (c.g - c.b) / d;
    if (c.g < c.b) {
      h += 6.0;
    }
    h /= 6.0;
  } else if (mx == c.g) {
    h = ((c.b - c.r) / d + 2.0) / 6.0;
  } else {
    h = ((c.r - c.g) / d + 4.0) / 6.0;
  }
  return vec3(h, s, l);
}

void main() {
  vec2 uv = vUv * uvScale;
  vec4 px = texture2D(tDiffuse, uv);
  if (view > 0.5 && view < 1.5) {
    gl_FragColor = px;
    return;
  }
  float a0 = max(px.a, 0.0);
  vec3 c = vec3(0.0);
  if (px.a > 0.000001) {
    c = px.rgb / px.a;
  }
  float d;
  if (matchMode > 0.5 && matchMode < 1.5) {
    vec3 hc = lckHsl(c);
    vec3 hk = lckHsl(keyColor);
    if (hc.y < 0.02) {
      d = 1.0;
    } else {
      float dd = abs(hc.x - hk.x);
      d = min(dd, 1.0 - dd) * 2.0;
    }
  } else if (matchMode > 1.5) {
    float sc = c.r + c.g + c.b;
    float sk = keyColor.r + keyColor.g + keyColor.b;
    vec2 pc = sc <= 0.000001 ? vec2(1.0 / 3.0) : vec2(c.r / sc, c.g / sc);
    vec2 pk = sk <= 0.000001 ? vec2(1.0 / 3.0) : vec2(keyColor.r / sk, keyColor.g / sk);
    d = length(pc - pk) / 1.41421356;
  } else {
    d = length(c - keyColor) / 1.73205081;
  }
  float v;
  if (softness > 0.000001) {
    v = clamp((d - tolerance) / softness, 0.0, 1.0);
  } else if (d > tolerance) {
    v = 1.0;
  } else {
    v = 0.0;
  }
  if (keep > 0.5) {
    v = 1.0 - v;
  }
  if (view > 1.5) {
    float m = v * a0;
    gl_FragColor = vec4(m, m, m, 1.0);
    return;
  }
  gl_FragColor = px * v;
}

text./plugins/native-fx/shaders/fx_radialblur:
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform float density;
uniform float decay;
uniform float weight;
uniform vec2 center;

#ifdef DITHER
uniform float dither;
#endif

const int SAMPLES = 24;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(41.0, 289.0))) * 45758.5453);
}

void main() {
  vec2 uv = vUv;
  vec2 centerOffset = 0.5 + center.xy * 0.45;
  vec2 tuv = uv - centerOffset;
  float angleStep = density * 0.2 / float(SAMPLES);

#ifdef DITHER
  float noise = hash(floor(uv * resolution));
  float angleOffset = angleStep * (noise * 2.0 - 1.0) * dither;
  float c0 = cos(angleOffset);
  float s0 = sin(angleOffset);
  tuv = mat2(c0, -s0, s0, c0) * tuv;
#endif

#ifdef CONSTANT_BRIGHTNESS
  vec4 color = vec4(0.0);
#else
  vec2 sampleUV = tuv + centerOffset;
  vec4 color = texture2D(tDiffuse, sampleUV * uvScale) * 0.25;
#endif

  float wt = weight;
  float sum = 0.0;
  float aspect = resolution.x / resolution.y;
  float c = cos(angleStep);
  float s = sin(angleStep);
  mat2 rotPos = mat2(c, -s, s, c);
  mat2 rotNeg = mat2(c, s, -s, c);
  vec2 tuvPos = tuv;
  vec2 tuvNeg = tuv;

  vec2 pos = tuv + centerOffset;
  color += texture2D(tDiffuse, pos * uvScale) * wt;
  sum += wt;
  wt *= decay;

  for (int i = 0; i < SAMPLES / 2; i++) {
    tuvPos.x *= aspect;
    tuvPos = rotPos * tuvPos;
    tuvPos.x /= aspect;
    pos = tuvPos + centerOffset;
    color += texture2D(tDiffuse, pos * uvScale) * wt;
    sum += wt;

    tuvNeg.x *= aspect;
    tuvNeg = rotNeg * tuvNeg;
    tuvNeg.x /= aspect;
    pos = tuvNeg + centerOffset;
    color += texture2D(tDiffuse, pos * uvScale) * wt;
    sum += wt;
    wt *= decay;
  }

#ifdef CONSTANT_BRIGHTNESS
  color /= sum;
  gl_FragColor = color;
#else
  color *= 1.0 - dot(tuv, tuv) * 0.75;
  gl_FragColor = smoothstep(0.0, 1.0, color);
#endif
}

text./plugins/native-fx/shaders/fx_radialshad:
// Radial Shadow: single-pass shadow of the layer cast away from a point
// light source (radial scale k = 1 + distance/100 about the light point),
// tinted with the shadow color, blurred with a small fixed kernel, and
// composited behind the original. All sampling goes through uvScale, so no
// scratch targets are needed.
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform vec3 shadowColor;
uniform float shadowAlpha;
uniform vec2 lightSource;
uniform float projectionDistance;
uniform float colorInfluence;
uniform float renderMode;
uniform float softPx;
uniform float shadowOnly;

vec4 sampleLayer(vec2 luv) {
  if (luv.x < 0.0 || luv.x > 1.0 || luv.y < 0.0 || luv.y > 1.0) {
    return vec4(0.0);
  }
  return texture2D(tDiffuse, luv * uvScale);
}

vec4 shadowAt(vec2 luv) {
  float k = 1.0 + max(projectionDistance, 0.0) / 100.0;
  vec2 suv = lightSource + (luv - lightSource) / k;
  vec4 s = sampleLayer(suv);
  float sa = s.a;
  vec3 sc = sa > 0.00001 ? s.rgb / sa : vec3(0.0);
  float a = sa;
  if (renderMode > 0.5) {
    a = clamp(sa * (1.0 - sa) * 4.0, 0.0, 1.0);
  }
  a *= shadowAlpha;
  vec3 c = shadowColor + (sc - shadowColor) * clamp(colorInfluence, 0.0, 1.0);
  return vec4(c * a, a);
}

void main() {
  vec4 shadow;
  if (softPx <= 0.0) {
    shadow = shadowAt(vUv);
  } else {
    // 5x5 binomial blur over +/- softPx/2 layer pixels. A coarse but smooth
    // approximation for large radii; exact (single tap) at 0.
    vec2 stepUv = vec2((softPx * 0.125) / max(resolution.x, 1.0), (softPx * 0.125) / max(resolution.y, 1.0));
    vec4 sum = vec4(0.0);
    float wsum = 0.0;
    for (int j = -2; j <= 2; j++) {
      float wj = j == 0 ? 6.0 : ((j == 1 || j == -1) ? 4.0 : 1.0);
      for (int i = -2; i <= 2; i++) {
        float wi = i == 0 ? 6.0 : ((i == 1 || i == -1) ? 4.0 : 1.0);
        float w = wi * wj;
        sum += shadowAt(vUv + vec2(float(i), float(j)) * stepUv) * w;
        wsum += w;
      }
    }
    shadow = sum / wsum;
  }
  if (shadowOnly > 0.5) {
    gl_FragColor = shadow;
    return;
  }
  vec4 original = texture2D(tDiffuse, vUv * uvScale);
  gl_FragColor = original + shadow * (1.0 - original.a);
}

text./plugins/native-fx/shaders/fx_radiowaves:
// Radio Waves (NATIVE FX): analytic concentric waves from a producer point.
// Each live wave is one entry of the uniform tables (centre, radius,
// half-width, rotation, fade, color, shape); the pixel shader only evaluates
// the closed-form distance to each wave. No particle history.
uniform sampler2D tDiffuse;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

#define MAX_WAVES 24

uniform vec4 uWavesA[MAX_WAVES]; // cx, cy, radius, halfWidth (px, y down)
uniform vec4 uWavesB[MAX_WAVES]; // rotation, fade, opacity, sides (0 = circle)
uniform vec4 uWavesC[MAX_WAVES]; // stroke color rgb, color alpha
uniform vec4 uWavesD[MAX_WAVES]; // star inner factor (0 = plain polygon), spare, spare, spare
uniform float uWaveCount;
uniform float uProfile;   // 0..6 stroke profile
uniform float uComposite; // 1 = blend over the layer, 0 = waves on transparency

float zss(float e0, float e1, float x) {
  float t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 e = b - a;
  float t = clamp(dot(p - a, e) / max(dot(e, e), 1e-12), 0.0, 1.0);
  return length(p - (a + e * t));
}

// Signed distance to a regular polygon (starK == 0) or star outline with the
// given circumradius, centred at the origin. Vertices sit at relative angles
// 2*PI*k/sides (the top vertex first, matching the reference unit outline
// rotated by rot). Dihedral fold: every pixel maps into one sector, so only
// the two edges around the sector vertex are measured.
float polySD(vec2 dp, float R, float sides, float starK, float rot) {
  float r = length(dp);
  if (r < 1e-9) {
    return -R;
  }
  float an = 3.14159265 / sides;
  float theta = atan(dp.y, dp.x) - rot + 1.5707963;
  float a = mod(theta + an, 2.0 * an) - an;
  vec2 v = vec2(r * cos(a), abs(r * sin(a)));
  vec2 v0 = vec2(R, 0.0);
  vec2 v1;
  if (starK > 0.0) {
    v1 = vec2(starK * R * cos(an), starK * R * sin(an));
  } else {
    v1 = vec2(R * cos(2.0 * an), R * sin(2.0 * an));
  }
  float d = min(segDist(v, v0, v1), segDist(vec2(v.x, -v.y), v0, v1));
  vec2 e = v1 - v0;
  vec2 w = v - v0;
  float cross_ = e.x * w.y - e.y * w.x;
  return cross_ > 0.0 ? -d : d;
}

float profile(float u) {
  float c = clamp(u, -1.0, 1.0);
  int kind = int(uProfile + 0.5);
  if (kind == 1) {
    return (1.0 - c) * 0.5;
  } else if (kind == 2) {
    return (1.0 + c) * 0.5;
  } else if (kind == 3) {
    return 1.0 - abs(c);
  } else if (kind == 4) {
    return cos(c * 1.5707963);
  } else if (kind == 5) {
    return c < 0.0 ? 1.0 + c : 1.0;
  } else if (kind == 6) {
    return c > 0.0 ? 1.0 - c : 1.0;
  }
  return 1.0;
}

vec4 over(vec4 dst, vec4 src) {
  return src + dst * (1.0 - src.a);
}

void main() {
  vec2 p = vec2(vUv.x * resolution.x, (1.0 - vUv.y) * resolution.y);
  vec4 out_;
  if (uComposite > 0.5) {
    out_ = texture2D(tDiffuse, vUv * uvScale);
  } else {
    out_ = vec4(0.0);
  }
  int count = int(min(uWaveCount + 0.5, float(MAX_WAVES)));
  for (int i = 0; i < MAX_WAVES; i++) {
    if (i >= count) {
      break;
    }
    vec4 A = uWavesA[i];
    vec4 B = uWavesB[i];
    vec2 dp = p - A.xy;
    float d;
    if (B.w < 0.5) {
      d = length(dp) - A.z;
    } else {
      d = polySD(dp, A.z, B.w, uWavesD[i].x, B.x);
    }
    float hw = max(A.w, 1e-4);
    float cov = clamp((hw - abs(d)) + 0.5, 0.0, 1.0);
    if (cov <= 0.0) {
      continue;
    }
    vec4 C = uWavesC[i];
    float a = cov * profile(d / hw) * B.y * B.z * C.a;
    if (a <= 0.0) {
      continue;
    }
    out_ = over(out_, vec4(C.rgb * a, a));
  }
  gl_FragColor = out_;
}

// Text field overlay (NATIVE FX, shared by Numbers and Timecode): composites
// a CPU-rasterised glyph coverage texture (R = fill, G = stroke ring) with
// fill/stroke display options over the layer (or on transparency), plus an
// optional solid box behind the text (Timecode). Coverage bytes are analytic
// per-pixel values computed in JS, identical on every machine; rows are
// uploaded flipped so sampling uses plain vUv.
uniform sampler2D tDiffuse;
uniform sampler2D uText;
varying vec2 vUv;
uniform vec2 uvScale;
uniform vec2 resolution;

uniform vec4 uFill;     // straight rgb + alpha
uniform vec4 uStroke;   // straight rgb + alpha
uniform float uDisplay; // 0 fill only, 1 stroke only, 2 fill over stroke, 3 stroke over fill
uniform float uComposite; // 1 = over the layer, 0 = text on transparency
uniform vec4 uBoxRect;  // x0, x1, y0, y1 in buffer px (y down), valid when uBoxOn > 0.5
uniform vec4 uBoxColor; // straight rgb + alpha (opacity baked in)
uniform float uBoxOn;

vec4 over(vec4 dst, vec4 src) {
  return src + dst * (1.0 - src.a);
}

vec4 tint(vec4 c, float a0) {
  float a = clamp(a0 * c.a, 0.0, 1.0);
  return vec4(c.rgb * a, a);
}

void main() {
  vec4 out_;
  if (uComposite > 0.5) {
    out_ = texture2D(tDiffuse, vUv * uvScale);
  } else {
    out_ = vec4(0.0);
  }
  if (uBoxOn > 0.5) {
    float fx = vUv.x * resolution.x;
    float fy = (1.0 - vUv.y) * resolution.y;
    float cy = clamp(fy - uBoxRect.z + 0.5, 0.0, 1.0) * clamp(uBoxRect.w - fy + 0.5, 0.0, 1.0);
    if (cy > 0.0) {
      float cx = clamp(fx - uBoxRect.x + 0.5, 0.0, 1.0) * clamp(uBoxRect.y - fx + 0.5, 0.0, 1.0);
      float k = cx * cy * uBoxColor.a;
      if (k > 0.0) {
        out_ = over(out_, vec4(uBoxColor.rgb * k, k));
      }
    }
  }
  vec2 cov = texture2D(uText, vUv).rg;
  vec4 fill = tint(uFill, cov.x);
  vec4 stroke = tint(uStroke, cov.y);
  int mode = int(uDisplay + 0.5);
  if (mode == 1) {
    out_ = over(out_, stroke);
  } else if (mode == 2) {
    out_ = over(over(out_, stroke), fill);
  } else if (mode == 3) {
    out_ = over(over(out_, fill), stroke);
  } else {
    out_ = over(out_, fill);
  }
  gl_FragColor = out_;
}

text./plugins/native-fx/shaders/fx_timediffer:
// Time Difference (Native FX): difference between the layer now and the layer
// at a time offset. The two frames arrive as premultiplied textures; the
// arithmetic below mirrors EffectCraft's CPU/GPU time_difference (unpremultiply,
// gain 1 + contrast/25, optional absolute value, nine alpha-channel modes,
// re-premultiply). Sampled with uv * uvScale because CM3 effect buffers can be
// larger than the layer.
precision highp float;

uniform sampler2D tBase;
uniform sampler2D tOther;
uniform float uGain;
uniform int uAbs;
uniform int uAlphaMode;

varying vec2 vUvScaled;

vec4 unpremul(vec4 color) {
  if (color.a > 0.0) {
    return vec4(color.rgb / color.a, color.a);
  }
  return vec4(0.0, 0.0, 0.0, max(color.a, 0.0));
}

void main() {
  vec4 current = unpremul(texture2D(tBase, vUvScaled));
  vec4 target = unpremul(texture2D(tOther, vUvScaled));
  vec3 diff = current.rgb - target.rgb;
  vec3 rgb;
  if (uAbs != 0) {
    rgb = clamp(abs(diff) * uGain, vec3(0.0), vec3(1.0));
  } else {
    rgb = clamp(0.5 + diff * 0.5 * uGain, vec3(0.0), vec3(1.0));
  }
  float brightest = max(max(rgb.r, rgb.g), rgb.b);
  float darkest = min(min(rgb.r, rgb.g), rgb.b);
  float lightness = (brightest + darkest) * 0.5;
  float alpha = current.a;
  if (uAlphaMode == 1) {
    alpha = target.a;
  } else if (uAlphaMode == 2) {
    alpha = (current.a + target.a) * 0.5;
  } else if (uAlphaMode == 3) {
    alpha = max(current.a, target.a);
  } else if (uAlphaMode == 4) {
    alpha = 1.0;
  } else if (uAlphaMode == 5) {
    alpha = lightness;
  } else if (uAlphaMode == 6) {
    alpha = brightest;
  } else if (uAlphaMode == 7) {
    alpha = abs(current.a - target.a) * uGain;
  } else if (uAlphaMode == 8) {
    alpha = clamp(abs(current.a - target.a) * uGain, 0.0, 1.0);
    rgb = vec3(1.0);
  }
  alpha = clamp(alpha, 0.0, 1.0);
  gl_FragColor = vec4(rgb * alpha, alpha);
}

text./plugins/native-fx/shaders/fx_timedispla:
// Time Displacement (Native FX): one gather pass per sampled time slice. Each
// output pixel takes the slice frame whose index matches the displacement map
// luminance at that pixel (Rec.709 luma of the unpremultiplied map color,
// mid grey when the map is transparent, exactly like EffectCraft's
// time_displacement); every other pixel keeps the running accumulation, which
// starts as the current input so the zero-offset slice needs no tap. The map
// is the layer itself unless the Layer Input plugin resolves another video
// track. Sampled with uv * uvScale because CM3 effect buffers can be larger
// than the layer.
precision highp float;

uniform sampler2D tAcc;
uniform sampler2D tSlice;
uniform sampler2D tMap;
uniform int uSlice;
uniform int uSlices;
uniform vec2 uMapScale;
uniform vec2 uMapOffset;

varying vec2 vUvScaled;

float mapLuma(vec3 color) {
  return 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
}

void main() {
  vec2 mapUv = vUvScaled * uMapScale + uMapOffset;
  vec4 map = texture2D(tMap, mapUv);
  float luma = 0.5;
  if (map.a > 0.0) {
    luma = mapLuma(map.rgb / map.a);
  }
  int slice = int(floor(luma * float(uSlices - 1) + 0.5));
  // GLSL ES 1.00 has no integer min/max overloads; clamp with branches.
  if (slice < 0) {
    slice = 0;
  }
  if (slice > uSlices - 1) {
    slice = uSlices - 1;
  }
  if (slice == uSlice) {
    gl_FragColor = texture2D(tSlice, vUvScaled);
  } else {
    gl_FragColor = texture2D(tAcc, vUvScaled);
  }
}

text./plugins/native-fx/smart-motion-blur/com:
precision highp float;
varying vec2 vUv;
uniform vec2 uProject;
uniform float uLimit;

vec4 features(vec4 c) {
    return vec4(dot(c.rgb, vec3(0.299, 0.587, 0.114)), (c.r - c.b) * 0.5,
                (c.g - (c.r + c.b) * 0.5) * 0.5, c.a * 0.7);
}
vec2 decodeFlow(vec4 c) {
#ifdef FLOW_PACKED
    vec4 b = floor(c * 255.0 + 0.5);
    return (vec2(b.r * 256.0 + b.g, b.b * 256.0 + b.a) - 32768.0) * (256.0 / 32767.0);
#else
    return c.rg;
#endif
}
vec4 encodeFlow(vec2 v) {
    float speed = length(v);
    v *= min(1.0, uLimit / max(speed, 0.000001));
#ifdef FLOW_PACKED
