uniform vec2 uScale;
uniform vec2 uSourceSize;
void main() {
    // A separable 1,2,1 Gaussian, evaluated in one pass. Source texel centers
    // remain inside the active region even when its allocation is larger.
    vec4 sum = vec4(0.0);
    vec2 lo = 0.5 / uSourceSize, hi = uScale - lo;
