        for (int x = 0; x < 2; x++) {
            vec2 p = first + vec2(float(x), float(y));
            if (p.x >= uSourceSize.x || p.y >= uSourceSize.y) continue;
            vec4 c = texture2D(uImage, (p + 0.5) / uSourceSize);
            maximum = max(maximum, c);
            sum += c;
            count += 1.0;
        }
    gl_FragColor = vec4(mix(maximum.rg, sum.rg / max(count, 1.0), uAverage), maximum.ba);
}

text./plugins/native-fx/smart-motion-blur/ref:
uniform sampler2D uCurrent;
uniform sampler2D uOther;
uniform sampler2D uFlow;
uniform sampler2D uWarp;
uniform vec2 uSize;
uniform float uSmoothness;

void main() {
    vec2 e = 1.0 / uSize;
    vec4 a = features(texture2D(uCurrent, vUv));
    vec2 sum = vec2(0.0);
    float weights = 0.0;
    for (int axis = 0; axis < 4; axis++) {
        vec2 off = axis == 0   ? vec2(e.x, 0.0)
                   : axis == 1 ? vec2(-e.x, 0.0)
                   : axis == 2 ? vec2(0.0, e.y)
                               : vec2(0.0, -e.y);
        vec4 c = features(texture2D(uCurrent, vUv + off));
        float w = exp(-dot(a - c, a - c) * 60.0) + 0.00001;
        sum += decodeFlow(texture2D(uFlow, vUv + off)) * w;
        weights += w;
    }
    vec2 mean = sum / weights * uSize / uProject;
    vec2 base = decodeFlow(texture2D(uWarp, vUv)) * uSize / uProject;
    vec2 q = vUv + base / uSize;
    vec4 b = features(texture2D(uOther, q));
    vec4 gx = 0.5 * (features(texture2D(uOther, q + vec2(e.x, 0.0))) -
                     features(texture2D(uOther, q - vec2(e.x, 0.0))));
    vec4 gy = 0.5 * (features(texture2D(uOther, q + vec2(0.0, e.y))) -
                     features(texture2D(uOther, q - vec2(0.0, e.y))));
    vec4 residual = b - a + gx * (mean.x - base.x) + gy * (mean.y - base.y);
    vec4 w = inversesqrt(residual * residual + vec4(0.0001));
    float lambda = 0.02 + uSmoothness * 0.18;
    float xx = dot(w * gx, gx) + lambda, yy = dot(w * gy, gy) + lambda, xy = dot(w * gx, gy);
    vec2 rhs = vec2(dot(w * gx, residual), dot(w * gy, residual));
    float det = max(xx * yy - xy * xy, 0.000001);
    vec2 correction = vec2(yy * rhs.x - xy * rhs.y, xx * rhs.y - xy * rhs.x) / det;
    vec2 result = mean - clamp(correction, -1.0, 1.0);
    gl_FragColor = encodeFlow(result * uProject / uSize);
}

text./plugins/native-fx/smart-motion-blur/see:
uniform sampler2D uCurrent;
uniform sampler2D uOther;
uniform sampler2D uFlow;
uniform vec2 uSize;
uniform vec2 uFlowSize;
uniform float uCoarse;
uniform float uStep;

float cost(vec2 velocity) {
    vec2 d = velocity / uProject;
    vec4 center = features(texture2D(uCurrent, vUv));
    float sum = 0.0, weights = 0.0;
    for (int y = -2; y <= 2; y++) {
        for (int x = -2; x <= 2; x++) {
            if (uCoarse < 0.5 && uStep >= 1.0 && (abs(float(x)) > 1.0 || abs(float(y)) > 1.0))
                continue;
            vec2 p = vUv + vec2(float(x), float(y)) / uSize;
            vec4 a = features(texture2D(uCurrent, p));
            vec4 b = features(texture2D(uOther, p + d));
            float w = 0.1 + 0.9 * exp(-dot(a - center, a - center) * 12.0);
            sum += robust(a - b) * w;
            weights += w;
        }
    }
    // Luma gradient constancy adds edge orientation without dropping chroma
    // or alpha information from the patch term.
    vec2 e = vec2(1.0 / uSize.x, 0.0), f = vec2(0.0, 1.0 / uSize.y);
    vec2 ga =
        vec2(features(texture2D(uCurrent, vUv + e)).r - features(texture2D(uCurrent, vUv - e)).r,
             features(texture2D(uCurrent, vUv + f)).r - features(texture2D(uCurrent, vUv - f)).r);
    vec2 gb = vec2(
        features(texture2D(uOther, vUv + d + e)).r - features(texture2D(uOther, vUv + d - e)).r,
        features(texture2D(uOther, vUv + d + f)).r - features(texture2D(uOther, vUv + d - f)).r);
    return sum / weights + 0.1 * length(ga - gb);
}
void main() {
    vec2 base = vec2(0.0);
    if (uCoarse < 0.5) base = flowAt(uFlow, vUv, uFlowSize);
    vec2 best = base;
    float bestCost = cost(best);
    float zeroCost = cost(vec2(0.0));
    if (zeroCost < bestCost - 0.000001) {
        best = vec2(0.0);
        bestCost = zeroCost;
    }
    // Constant loop bounds are required by GLSL ES 1.00. Fine levels evaluate
    // only the central 3x3 candidates.
    for (int y = -4; y <= 4; y++) {
        for (int x = -4; x <= 4; x++) {
            if (uCoarse < 0.5 && (abs(float(x)) > 1.0 || abs(float(y)) > 1.0)) continue;
            vec2 v = base + vec2(float(x), float(y)) * uStep * uProject / uSize;
            if (length(v) > uLimit) continue;
            float c = cost(v);
            if (c < bestCost - 0.000001 ||
                (uCoarse > 0.5 && abs(c - bestCost) <= 0.000001 && dot(v, v) < dot(best, best))) {
                best = v;
                bestCost = c;
            }
        }
    }
    gl_FragColor = encodeFlow(best);
}

text./plugins/native-fx/smart-motion-blur/til:
uniform sampler2D uFlow;
uniform vec2 uFlowSize;
uniform vec2 uProcessing;
uniform float uDelta;
uniform float uSign;
void main() {
    vec2 first = floor(gl_FragCoord.xy - 0.5) * 16.0;
    vec2 best = vec2(0.0);
    for (int y = 0; y < 16; y++)
        for (int x = 0; x < 16; x++) {
            vec2 p = first + vec2(float(x), float(y)) + 0.5;
            if (p.x > uProcessing.x || p.y > uProcessing.y) continue;
            vec2 f = flowAt(uFlow, p / uProcessing, uFlowSize) * uSign / uDelta;
            if (dot(f, f) > dot(best, best)) best = f;
        }
    gl_FragColor = encodeFlow(best);
}
